  const cut = t.slice(0, max);
  const m = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '), cut.lastIndexOf('\n'), cut.lastIndexOf('…'));
  return (m > max * 0.5 ? cut.slice(0, m + 1) : cut.slice(0, cut.lastIndexOf(' ')) + '…').trim();
};
